custom_css:
/*
 * 禁果酒馆 / Forbidden Apple Tavern v1
 * SillyTavern custom CSS theme.
 *
 * 基于原始 CSS 模板二创。
 * 原模板编写/整理：墨千尾（discord@这对吗/inkfoxxxx）。
 * 注释部分几乎完全纯手打，代码部分半手打；发布时请不要抹掉原作者 ID。
 * 部分代码来源于教程贴分享，发布时请保留作者 ID。
 *
 * 二创主题方向：红苹果、蛇、复古拼贴、清透果冻、头像居中。
 * 硬性边界：不改 SillyTavern HTML，不改既有类名/ID/选择器。
 */

/* ===== 一、全局 ===== */
:root {
  --fa-bg: #fff8ed;
  --fa-panel: rgba(255, 248, 237, 0.86);
  --fa-panel-strong: rgba(255, 242, 214, 0.94);
  --fa-red: #9e1717;
  --fa-red-bright: #c7352d;
  --fa-red-dark: #5e0a0d;
  --fa-flesh: #fff2d6;
  --fa-cream: #fff8ed;
  --fa-seed: #4a2419;
  --fa-snake: #324d35;
  --fa-snake-light: #6f8b59;
  --fa-text: #2a1714;
  --fa-muted: #7b5a50;
  --fa-border: rgba(94, 10, 13, 0.22);
  --fa-border-strong: rgba(158, 23, 23, 0.42);
  --fa-shadow: rgba(74, 36, 25, 0.16);
  --fa-glow: rgba(199, 53, 45, 0.22);
  --fa-radius-lg: 22px;
  --fa-radius-md: 16px;
  --fa-radius-sm: 10px;
  --fa-chat-width: min(860px, calc(100% - 28px));
  --fa-user-frame-image: url("/css/themes/forbidden-apple-tavern/avatar-frames/user-frame-01.png");
  --fa-char-frame-image: url("/css/themes/forbidden-apple-tavern/avatar-frames/char-frame-01.png");

  --SmartThemeBodyColor: var(--fa-text);
  --SmartThemeEmColor: #8c2a24;
  --SmartThemeUnderlineColor: #a83a2f;
  --SmartThemeQuoteColor: #42633f;
  --SmartThemeBlurTintColor: rgba(255, 248, 237, 0.78);
  --SmartThemeChatTintColor: rgba(255, 250, 242, 0.78);
  --SmartThemeUserMesBlurTintColor: rgba(199, 53, 45, 0.14);
  --SmartThemeBotMesBlurTintColor: rgba(255, 242, 214, 0.86);
  --SmartThemeShadowColor: transparent;
  --SmartThemeBorderColor: var(--fa-border);
  --shadowWidth: 0;
}

body[data-user-frame="1"] { --fa-user-frame-image: url("/css/themes/forbidden-apple-tavern/avatar-frames/user-frame-01.png"); }
body[data-user-frame="2"] { --fa-user-frame-image: url("/css/themes/forbidden-apple-tavern/avatar-frames/user-frame-02.png"); }
