body[data-user-frame="5"] { --fa-user-frame-image: url("/css/themes/forbidden-apple-tavern/avatar-frames/user-frame-05.png"); }
body[data-user-frame="6"] { --fa-user-frame-image: url("/css/themes/forbidden-apple-tavern/avatar-frames/user-frame-06.png"); }
body[data-user-frame="7"] { --fa-user-frame-image: url("/css/themes/forbidden-apple-tavern/avatar-frames/user-frame-07.png"); }
body[data-user-frame="8"] { --fa-user-frame-image: url("/css/themes/forbidden-apple-tavern/avatar-frames/user-frame-08.png"); }
