body[data-char-frame="1"] { --fa-char-frame-image: url("/css/themes/forbidden-apple-tavern/avatar-frames/char-frame-01.png"); }
body[data-char-frame="2"] { --fa-char-frame-image: url("/css/themes/forbidden-apple-tavern/avatar-frames/char-frame-02.png"); }
body[data-char-frame="3"] { --fa-char-frame-image: url("/css/themes/forbidden-apple-tavern/avatar-frames/char-frame-03.png"); }
body[data-char-frame="4"] { --fa-char-frame-image: url("/css/themes/forbidden-apple-tavern/avatar-frames/char-frame-04.png"); }
