body[data-char-frame="8"] { --fa-char-frame-image: url("/css/themes/forbidden-apple-tavern/avatar-frames/char-frame-08.png"); }
body[data-char-frame="9"] { --fa-char-frame-image: url("/css/themes/forbidden-apple-tavern/avatar-frames/char-frame-09.png"); }

html,
body {
  color: var(--fa-text) !important;
  font-family: "Segoe UI", "Microsoft YaHei UI", "PingFang SC", system-ui, sans-serif !important;
  background:
    radial-gradient(circle at 8% 14%, rgba(199, 53, 45, 0.14) 0 52px, transparent 53px),
    radial-gradient(circle at 92% 18%, rgba(94, 10, 13, 0.11) 0 42px, transparent 43px),
    radial-gradient(circle at 88% 86%, rgba(50, 77, 53, 0.12) 0 70px, transparent 71px),
    linear-gradient(135deg, #fffaf3 0%, #fff1e4 44%, #f8dfd7 100%) !important;
}

body::before,
body::after {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 0;
}

body::before {
  background:
    radial-gradient(ellipse at 14% 52%, rgba(158, 23, 23, 0.11) 0 18px, transparent 19px),
    radial-gradient(ellipse at 20% 58%, rgba(158, 23, 23, 0.09) 0 7px, transparent 8px),
    radial-gradient(ellipse at 78% 46%, rgba(74, 36, 25, 0.10) 0 6px, transparent 7px),
    radial-gradient(ellipse at 84% 52%, rgba(74, 36, 25, 0.09) 0 5px, transparent 6px);
  opacity: 0.9;
}

body::after {
  background:
    linear-gradient(108deg, transparent 0 11%, rgba(50, 77, 53, 0.16) 11.2%, transparent 11.6% 100%),
    linear-gradient(72deg, transparent 0 87%, rgba(50, 77, 53, 0.14) 87.2%, transparent 87.7% 100%);
  mask-image: radial-gradient(circle at center, transparent 0 30%, black 62%);
  opacity: 0.65;
}

body * {
  text-shadow: none !important;
}

a,
.interactable,
.menu_button,
.mes_button {
  transition: background-color 160ms ease, border-color 160ms ease, color 160ms ease, transform 160ms ease, opacity 160ms ease !important;
}

button,
.menu_button {
  border-radius: var(--fa-radius-sm) !important;
}

/* ===== 二、顶栏 ===== */
#top-bar {
  overflow: visible !important;
  border: 1px solid rgba(158, 23, 23, 0.24) !important;
  border-top: 0 !important;
  border-radius: 0 0 24px 24px !important;
  background:
    radial-gradient(circle at 18px 16px, rgba(255, 255, 255, 0.86) 0 2px, transparent 3px),
    linear-gradient(180deg, rgba(255, 255, 255, 0.62), rgba(255, 242, 214, 0.30)),
    linear-gradient(90deg, rgba(94, 10, 13, 0.72), rgba(199, 53, 45, 0.72), rgba(94, 10, 13, 0.72)) !important;
  box-shadow: 0 12px 32px rgba(94, 10, 13, 0.20) !important;
  backdrop-filter: blur(18px) saturate(1.28) !important;
  -webkit-backdrop-filter: blur(18px) saturate(1.28) !important;
}

#top-bar::before {
  content: "";
  position: absolute;
  top: 8px;
  left: 18px;
  width: 34px;
  height: 28px;
  border-radius: 48% 52% 54% 46% / 55% 48% 52% 45%;
  background:
    radial-gradient(circle at 63% 22%, rgba(255, 248, 237, 0.78) 0 4px, transparent 5px),
    radial-gradient(circle at 48% 38%, rgba(255, 242, 214, 0.72) 0 10px, transparent 11px),
    linear-gradient(135deg, #d65a4c 0%, #9e1717 48%, #5e0a0d 100%);
  border: 1px solid rgba(255, 242, 214, 0.70);
  box-shadow: 0 5px 15px rgba(94, 10, 13, 0.32);
}

#top-bar::after {
  content: "";
  position: absolute;
  top: 11px;
  left: 42px;
  width: 54px;
  height: 24px;
  border: 2px solid rgba(50, 77, 53, 0.55);
  border-left: 0;
  border-bottom-color: transparent;
  border-radius: 0 999px 999px 0;
  transform: rotate(-8deg);
  opacity: 0.86;
}

#top-settings-holder {
  z-index: 3007 !important;
  align-items: center !important;
  gap: 0 !important;
}

#top-settings-holder .drawer {
  width: 100% !important;
  flex: 1 1 0 !important;
  min-width: 0 !important;
}

#top-settings-holder .drawer-icon {
  position: relative !important;
  width: 34px !important;
  height: 34px !important;
  padding: 0 !important;
  margin: 0 2px !important;
  font-size: 0 !important;
  border-radius: 14px !important;
  border: 1px solid rgba(255, 242, 214, 0.48) !important;
  background:
    radial-gradient(circle at 64% 26%, rgba(255, 255, 255, 0.8) 0 3px, transparent 4px),
    linear-gradient(145deg, rgba(255, 248, 237, 0.75), rgba(255, 242, 214, 0.35)),
    linear-gradient(135deg, #c7352d, #7e1014) !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.52), 0 5px 13px rgba(94, 10, 13, 0.20) !important;
  opacity: 0.72 !important;
}

#top-settings-holder .drawer-icon::before {
  content: "" !important;
  position: absolute !important;
  left: 8px;
  top: 9px;
  width: 18px;
  height: 16px;
  border-radius: 48% 52% 54% 46% / 55% 50% 50% 45%;
  background:
    radial-gradient(circle at 64% 25%, rgba(255, 248, 237, 0.85) 0 2px, transparent 3px),
    linear-gradient(135deg, #f06b5e, #9e1717 62%, #5e0a0d);
}

#top-settings-holder .drawer-icon::after {
  content: "" !important;
  position: absolute;
  left: 18px;
  top: 5px;
  width: 10px;
  height: 6px;
  border-radius: 100% 0 100% 0;
  background: #6f8b59;
  transform: rotate(-26deg);
  box-shadow: -8px 18px 0 -4px rgba(50, 77, 53, 0.46);
}

#top-settings-holder .drawer-icon:hover,
#top-settings-holder .drawer .drawer-icon.openIcon {
  opacity: 1 !important;
  transform: translateY(-1px) scale(1.04);
  border-color: rgba(255, 248, 237, 0.85) !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.66), 0 8px 18px rgba(94, 10, 13, 0.28) !important;
}

#top-settings-holder .drawer-icon.fa-sliders::before,
#top-settings-holder .drawer-icon.fa-sliders-h::before {
  border-radius: 48% 52% 54% 46% / 55% 50% 50% 45%;
  background:
    linear-gradient(#fff2d6 0 0) 4px 5px / 12px 2px no-repeat,
    linear-gradient(#fff2d6 0 0) 2px 9px / 15px 2px no-repeat,
    linear-gradient(#fff2d6 0 0) 6px 13px / 10px 2px no-repeat,
    radial-gradient(circle at 64% 25%, rgba(255, 248, 237, 0.88) 0 2px, transparent 3px),
    linear-gradient(135deg, #f06b5e, #9e1717 62%, #5e0a0d) !important;
}

#top-settings-holder .drawer-icon.fa-sliders::after,
#top-settings-holder .drawer-icon.fa-sliders-h::after {
  width: 9px;
  height: 6px;
  background: #6f8b59;
  box-shadow: -10px 18px 0 -4px #fff2d6, 8px 18px 0 -4px #fff2d6 !important;
}

#top-settings-holder .drawer-icon.fa-plug::before,
#top-settings-holder .drawer-icon.fa-plug-circle-exclamation::before {
  left: 9px;
  top: 8px;
  width: 17px;
  height: 18px;
  border-radius: 999px 8px 999px 10px;
  background:
    linear-gradient(90deg, transparent 0 52%, rgba(255, 242, 214, 0.84) 53% 61%, transparent 62%),
    linear-gradient(135deg, #91a96d, #324d35 68%, #263f2b) !important;
  transform: rotate(-18deg);
}

#top-settings-holder .drawer-icon.fa-plug::after,
#top-settings-holder .drawer-icon.fa-plug-circle-exclamation::after {
  left: 9px;
  top: 22px;
  width: 17px;
  height: 5px;
  border-radius: 999px;
  background: #fff2d6;
  box-shadow: 4px -17px 0 -2px rgba(158, 23, 23, 0.72) !important;
}

#top-settings-holder .drawer-icon.fa-font::before {
  content: "A" !important;
  left: 8px;
  top: 6px;
  width: 18px;
  height: 20px;
  border-radius: 58% 16% 58% 18%;
  color: #fff2d6;
  font: 900 16px/20px Georgia, serif;
  text-align: center;
  background: linear-gradient(135deg, #d65a4c, #7e1014) !important;
}

#top-settings-holder .drawer-icon.fa-font::after {
  left: 21px;
  top: 5px;
  width: 10px;
  height: 6px;
  background: #6f8b59;
  box-shadow: -15px 20px 0 -4px rgba(255, 242, 214, 0.82) !important;
}

#top-settings-holder .drawer-icon.fa-book-atlas::before {
  left: 7px;
  top: 10px;
  width: 20px;
  height: 15px;
  border-radius: 9px 9px 5px 5px;
  background:
    linear-gradient(90deg, #fff2d6 0 45%, rgba(94, 10, 13, 0.28) 46% 54%, #fff2d6 55% 100%),
    linear-gradient(135deg, #d65a4c, #7e1014) !important;
  box-shadow: inset 0 0 0 2px rgba(158, 23, 23, 0.46);
}

#top-settings-holder .drawer-icon.fa-book-atlas::after {
  left: 8px;
  top: 5px;
  width: 20px !important;
  height: 21px;
  border: 2px solid rgba(50, 77, 53, 0.74);
  border-left: 0;
  border-bottom-color: transparent;
  border-radius: 0 999px 999px 0;
  background: transparent !important;
  transform: rotate(-12deg);
  box-shadow: none !important;
}

#top-settings-holder .drawer-icon.fa-user-cog::before,
#top-settings-holder .drawer-icon.fa-user::before {
  left: 8px;
  top: 7px;
  width: 18px;
  height: 19px;
  clip-path: none;
  border-radius: 50%;
  background:
    radial-gradient(circle at 50% 37%, #fff2d6 0 4px, transparent 5px),
    radial-gradient(ellipse at 50% 78%, #fff2d6 0 8px, transparent 9px),
    linear-gradient(135deg, #d65a4c, #8e1217 65%, #5e0a0d) !important;
}

#top-settings-holder .drawer-icon.fa-user-cog::after,
#top-settings-holder .drawer-icon.fa-user::after {
  left: 21px;
  top: 5px;
  width: 9px;
  height: 6px;
  background: #6f8b59;
  box-shadow: -17px 19px 0 -4px rgba(50, 77, 53, 0.48) !important;
}

#top-settings-holder .drawer-icon.fa-panorama::before,
#top-settings-holder .drawer-icon.fa-image::before {
  left: 7px;
  top: 8px;
  width: 20px;
  height: 18px;
  border-radius: 7px;
  background:
    radial-gradient(circle at 66% 32%, #fff2d6 0 3px, transparent 4px),
    linear-gradient(155deg, transparent 0 42%, rgba(255, 242, 214, 0.92) 43% 56%, transparent 57%),
    linear-gradient(135deg, #d65a4c, #7e1014) !important;
  box-shadow: inset 0 0 0 2px rgba(255, 242, 214, 0.72);
}

#top-settings-holder .drawer-icon.fa-panorama::after,
#top-settings-holder .drawer-icon.fa-image::after {
  left: 22px;
  top: 4px;
  width: 9px;
  height: 6px;
  background: #6f8b59;
  box-shadow: -18px 22px 0 -5px rgba(158, 23, 23, 0.72) !important;
}

#top-settings-holder .drawer-icon.fa-cubes::before {
  left: 7px;
  top: 8px;
  width: 20px;
  height: 18px;
  border-radius: 6px;
  background:
    radial-gradient(circle at 30% 32%, #c7352d 0 4px, transparent 5px),
    radial-gradient(circle at 68% 36%, #9e1717 0 4px, transparent 5px),
    radial-gradient(circle at 52% 70%, #fff2d6 0 4px, transparent 5px),
    linear-gradient(135deg, rgba(94, 10, 13, 0.72), rgba(255, 242, 214, 0.62)) !important;
  box-shadow: 7px 6px 0 -4px #7e1014, -7px 7px 0 -4px #fff2d6;
}

#top-settings-holder .drawer-icon.fa-cubes::after {
  left: 22px;
  top: 5px;
  width: 9px;
  height: 6px;
  background: #6f8b59;
  box-shadow: -19px 21px 0 -5px rgba(50, 77, 53, 0.42) !important;
}

#top-settings-holder .drawer-icon.fa-face-smile::before {
  left: 8px;
  top: 8px;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background:
    radial-gradient(circle at 35% 42%, #5e0a0d 0 1px, transparent 2px),
    radial-gradient(circle at 65% 42%, #5e0a0d 0 1px, transparent 2px),
    radial-gradient(ellipse at 50% 64%, transparent 0 4px, #fff2d6 5px, transparent 6px),
    linear-gradient(135deg, #f06b5e, #9e1717) !important;
}

#top-settings-holder .drawer-icon.fa-face-smile::after {
  left: 20px;
  top: 5px;
  width: 10px;
  height: 6px;
  background: #6f8b59;
  box-shadow: -15px 20px 0 -4px rgba(255, 242, 214, 0.78) !important;
}

#top-settings-holder .drawer-icon.fa-address-card::before {
  left: 6px;
  top: 9px;
  width: 22px;
  height: 16px;
  border-radius: 5px 12px 12px 5px !important;
  background:
    linear-gradient(#5e0a0d 0 0) 10px 5px / 10px 2px no-repeat,
    linear-gradient(#5e0a0d 0 0) 10px 9px / 8px 2px no-repeat,
    radial-gradient(circle at 6px 8px, #fff2d6 0 4px, transparent 5px),
    linear-gradient(135deg, #fff2d6, #d65a4c 54%, #8e1217) !important;
}

#top-settings-holder .drawer-icon.fa-address-card::after {
  left: 22px;
  top: 5px;
  width: 9px;
  height: 6px;
  background: #6f8b59;
  box-shadow: -20px 22px 0 -5px rgba(158, 23, 23, 0.78) !important;
}

#top-settings-holder .drawer-icon.fa-bars-progress::before {
  left: 7px;
  top: 8px;
  width: 20px;
  height: 18px;
  border-radius: 7px;
  background:
    radial-gradient(circle at 4px 5px, #fff2d6 0 2px, transparent 3px),
    radial-gradient(circle at 4px 10px, #fff2d6 0 2px, transparent 3px),
    radial-gradient(circle at 4px 15px, #fff2d6 0 2px, transparent 3px),
    linear-gradient(#fff2d6 0 0) 8px 4px / 9px 2px no-repeat,
    linear-gradient(#fff2d6 0 0) 8px 9px / 12px 2px no-repeat,
    linear-gradient(#fff2d6 0 0) 8px 14px / 7px 2px no-repeat,
    linear-gradient(135deg, #c7352d, #7e1014) !important;
}

#top-settings-holder .drawer-icon.fa-bars-progress::after {
  left: 21px;
  top: 5px;
  width: 9px;
  height: 6px;
  background: #6f8b59;
  box-shadow: -18px 20px 0 -4px rgba(255, 242, 214, 0.78) !important;
}

.drawer-content {
  isolation: isolate;
  color: var(--fa-text) !important;
  border: 1px solid rgba(158, 23, 23, 0.28) !important;
  border-radius: 24px !important;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.70), rgba(255, 242, 214, 0.68)),
    radial-gradient(circle at 96% 5%, rgba(199, 53, 45, 0.16) 0 62px, transparent 64px),
    radial-gradient(circle at 4% 94%, rgba(50, 77, 53, 0.12) 0 78px, transparent 80px),
    var(--fa-panel) !important;
  box-shadow: 0 18px 46px rgba(74, 36, 25, 0.18) !important;
  backdrop-filter: blur(22px) saturate(1.18) !important;
  -webkit-backdrop-filter: blur(22px) saturate(1.18) !important;
}

.drawer-content::before {
  content: "";
  position: absolute;
  inset: 10px;
  z-index: -1;
  pointer-events: none;
  border: 1px dashed rgba(158, 23, 23, 0.16);
  border-radius: 18px;
  background:
    linear-gradient(112deg, transparent 0 8%, rgba(50, 77, 53, 0.13) 8.15%, transparent 8.55% 100%),
    radial-gradient(ellipse at 92% 18%, rgba(74, 36, 25, 0.10) 0 5px, transparent 6px),
    radial-gradient(ellipse at 95% 24%, rgba(74, 36, 25, 0.08) 0 4px, transparent 5px);
}

.drawer-content::after {
  content: "";
  position: absolute;
  right: 16px;
  top: 14px;
  width: 54px;
  height: 46px;
  z-index: -1;
  pointer-events: none;
  opacity: 0.72;
  border-radius: 46% 54% 52% 48% / 54% 48% 52% 46%;
  background:
    radial-gradient(circle at 62% 24%, rgba(255, 248, 237, 0.82) 0 6px, transparent 7px),
    radial-gradient(circle at 50% 48%, rgba(255, 242, 214, 0.52) 0 18px, transparent 19px),
    linear-gradient(135deg, #d65a4c, #9e1717 62%, #5e0a0d);
  box-shadow: 0 8px 20px rgba(94, 10, 13, 0.18);
}

.drawer-content h1,
.drawer-content h2,
.drawer-content h3,
.drawer-content h4,
.drawer-content .standoutHeader {
  color: var(--fa-red-dark) !important;
}

.drawer-content input,
.drawer-content textarea,
.drawer-content select,
.drawer-content .text_pole,
.drawer-content .menu_button {
  border-color: rgba(158, 23, 23, 0.24) !important;
  border-radius: 12px !important;
}

.drawer-content input,
.drawer-content textarea,
.drawer-content select,
.drawer-content .text_pole {
  color: var(--fa-text) !important;
  background-color: rgba(255, 248, 237, 0.72) !important;
}

.drawer-content .menu_button:hover,
.drawer-content .interactable:hover {
  color: var(--fa-red) !important;
  background-color: rgba(199, 53, 45, 0.10) !important;
}

.drawer-content .inline-drawer-header,
.drawer-content .inline-drawer-toggle {
  min-height: 30px !important;
  color: var(--fa-text) !important;
  border: 1px solid rgba(158, 23, 23, 0.24) !important;
  border-radius: 12px !important;
  background:
    radial-gradient(circle at 98% 50%, rgba(50, 77, 53, 0.10), transparent 26%),
