    linear-gradient(180deg, rgba(255, 255, 255, 0.72), rgba(255, 242, 214, 0.64)),
    radial-gradient(circle at 10% 50%, rgba(199, 53, 45, 0.13), transparent 34%),
    var(--fa-panel) !important;
  box-shadow: 0 -12px 30px rgba(94, 10, 13, 0.14) !important;
