/* ===== 四、聊天区域 ===== */
#chat {
  position: relative !important;
  padding: 18px 0 12px !important;
  gap: 12px !important;
  background:
    linear-gradient(180deg, rgba(255, 250, 242, 0.86), rgba(255, 244, 226, 0.78)),
    radial-gradient(circle at 4% 26%, rgba(199, 53, 45, 0.10) 0 92px, transparent 94px),
    radial-gradient(circle at 96% 72%, rgba(50, 77, 53, 0.10) 0 118px, transparent 120px) !important;
  border-left: 1px solid rgba(158, 23, 23, 0.12) !important;
  border-right: 1px solid rgba(158, 23, 23, 0.12) !important;
  overflow-x: hidden !important;
}

#chat::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  background:
    radial-gradient(circle at 8% 16%, rgba(158, 23, 23, 0.12) 0 22px, transparent 23px),
    radial-gradient(circle at 91% 34%, rgba(158, 23, 23, 0.11) 0 16px, transparent 17px),
    radial-gradient(ellipse at 12% 82%, rgba(74, 36, 25, 0.12) 0 6px, transparent 7px),
    radial-gradient(ellipse at 16% 88%, rgba(74, 36, 25, 0.10) 0 5px, transparent 6px),
    radial-gradient(ellipse at 88% 14%, rgba(74, 36, 25, 0.09) 0 5px, transparent 6px),
    linear-gradient(105deg, transparent 0 9%, rgba(50, 77, 53, 0.16) 9.15%, transparent 9.55% 100%),
    linear-gradient(78deg, transparent 0 90%, rgba(50, 77, 53, 0.13) 90.2%, transparent 90.7% 100%);
  opacity: 0.75;
  mask-image: linear-gradient(90deg, black 0 18%, transparent 32% 68%, black 82% 100%);
}

#chat::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 22px;
  width: min(760px, 82%);
  height: calc(100% - 44px);
  transform: translateX(-50%);
  pointer-events: none;
  z-index: 0;
  border-left: 1px dashed rgba(158, 23, 23, 0.08);
  border-right: 1px dashed rgba(158, 23, 23, 0.08);
  border-radius: 36px;
}

.mes {
  z-index: 1;
  width: var(--fa-chat-width) !important;
  margin: 0 auto !important;
  padding: 16px 10px 8px !important;
