.mes[is_user="true"] .avatar::after {
  background-image: var(--fa-user-frame-image);
}

.mesIDDisplay,
.mes_timer,
.tokenCounterDisplay {
  margin-top: 2px !important;
  color: rgba(74, 36, 25, 0.58) !important;
  font-size: 0.72rem !important;
}

.mes .swipe_left {
  left: max(18px, calc(50% - 460px)) !important;
  bottom: 32px !important;
}

.mes .swipeRightBlock {
  right: max(18px, calc(50% - 460px)) !important;
  bottom: 10px !important;
}

.mes .mes_block {
  position: relative !important;
  order: 1 !important;
  width: min(100%, 820px) !important;
  padding: 14px 18px 16px !important;
  overflow: visible !important;
  border-radius: 26px !important;
  border: 1px solid var(--fa-border) !important;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.74), rgba(255, 242, 214, 0.76)),
    radial-gradient(circle at 98% 8%, rgba(50, 77, 53, 0.10), transparent 18%) !important;
  box-shadow: 0 10px 26px rgba(74, 36, 25, 0.11) !important;
}

.mes[is_user="true"] .mes_block {
  border-color: rgba(158, 23, 23, 0.36) !important;
  background:
    linear-gradient(180deg, rgba(255, 245, 238, 0.90), rgba(255, 224, 214, 0.78)),
    radial-gradient(circle at 6% 10%, rgba(199, 53, 45, 0.22), transparent 22%) !important;
}

.mes[is_user="false"] .mes_block {
  border-color: rgba(50, 77, 53, 0.24) !important;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.84), rgba(255, 242, 214, 0.78)),
    radial-gradient(circle at 96% 10%, rgba(50, 77, 53, 0.10), transparent 20%) !important;
}

.mes .mes_block::before {
  content: "";
  position: absolute;
  top: -10px;
  left: 50%;
  width: 48px;
  height: 18px;
  transform: translateX(-50%);
  border-radius: 0 0 999px 999px;
  border: 1px solid rgba(158, 23, 23, 0.20);
  border-top: 0;
  background: rgba(255, 242, 214, 0.78);
  box-shadow: inset 0 -1px 0 rgba(255, 255, 255, 0.62);
