.mes[is_user="true"] .mes_block::after {
  background:
    radial-gradient(circle at 60% 28%, rgba(255, 248, 237, 0.88) 0 4px, transparent 5px),
    linear-gradient(135deg, #d65a4c, #9e1717 68%, #5e0a0d);
}

.mes[is_user="false"] .mes_block::after {
  width: 36px;
  height: 20px;
  border: 2px solid rgba(50, 77, 53, 0.46);
  border-left: 0;
  border-bottom-color: transparent;
  border-radius: 0 999px 999px 0;
  background: transparent;
  transform: rotate(-12deg);
}

.mes .ch_name {
  justify-content: center !important;
  text-align: center !important;
  min-height: unset !important;
  margin: 0 0 7px !important;
  color: var(--fa-red-dark) !important;
}

.mes .ch_name .flex1,
.mes .ch_name .flex-container {
  justify-content: center !important;
}

.mes .name_text {
  font-weight: 800 !important;
  letter-spacing: 0 !important;
}

.mes .timestamp {
  color: var(--fa-muted) !important;
  font-weight: 500 !important;
}

.mes_buttons,
.mes_edit_buttons {
  position: absolute !important;
  right: 14px !important;
  top: 10px !important;
  color: var(--fa-muted) !important;
}

.mes .mes_text {
  color: var(--fa-text) !important;
  font-size: calc(var(--mainFontSize) * 1) !important;
  line-height: 1.72 !important;
  padding: 4px 8px 6px !important;
  max-width: 100% !important;
}

.mes .mes_text p {
  margin-bottom: 0.82em !important;
}

.mes .mes_text p:last-child {
  margin-bottom: 0 !important;
}

.mes .mes_text blockquote,
.mes_reasoning blockquote {
  border-left: 4px solid rgba(158, 23, 23, 0.42) !important;
  background: rgba(255, 242, 214, 0.46) !important;
  border-radius: 0 12px 12px 0 !important;
  padding: 8px 12px !important;
}

.mes .mes_text code,
.mes .mes_text pre,
.mes_reasoning code,
.mes_reasoning pre {
  color: #3a201c !important;
  background: rgba(255, 248, 237, 0.78) !important;
  border: 1px solid rgba(158, 23, 23, 0.18) !important;
  border-radius: 10px !important;
}

/* ===== 五、滚动条 + 滑动条 ===== */
::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}

::-webkit-scrollbar-track {
  background: rgba(255, 242, 214, 0.46);
  border-radius: 999px;
}

::-webkit-scrollbar-thumb {
  min-height: 44px;
  border: 2px solid rgba(255, 248, 237, 0.86);
  border-radius: 999px;
  background:
    radial-gradient(circle at 50% 20%, rgba(255, 242, 214, 0.86) 0 3px, transparent 4px),
    linear-gradient(180deg, #c7352d, #7e1014 58%, #324d35) !important;
}

::-webkit-scrollbar-thumb:hover {
  background:
    radial-gradient(circle at 50% 20%, rgba(255, 242, 214, 0.95) 0 3px, transparent 4px),
    linear-gradient(180deg, #e05b4f, #9e1717 58%, #42633f) !important;
}

input[type="range"] {
  accent-color: var(--fa-red);
}

input[type="range"]::-webkit-slider-thumb {
  border-radius: 50% !important;
  border: 2px solid var(--fa-flesh) !important;
  background:
    radial-gradient(circle at 62% 25%, rgba(255, 255, 255, 0.8) 0 3px, transparent 4px),
    linear-gradient(135deg, #d65a4c, #7e1014) !important;
  box-shadow: 0 3px 8px rgba(94, 10, 13, 0.28) !important;
}

/* ===== 六、输入框提示文字自定义 ===== */
#nonQRFormItems {
  position: relative !important;
}

#send_textarea::placeholder {
  color: transparent !important;
}

#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
  content: "咬一口苹果，再写下这句私语";
  position: absolute;
  left: 64px;
  right: 82px;
  top: 50%;
  transform: translateY(-50%);
  color: rgba(94, 10, 13, 0.46);
  font-size: 0.92rem;
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  pointer-events: none;
  z-index: 2;
}

#nonQRFormItems:has(#send_textarea:focus)::before {
  opacity: 0.48;
}

/* ===== 七、正则/脚本易读 + 防误触 ===== */
#saved_regex_scripts,
#saved_scoped_scripts,
#saved_preset_scripts,
#global-script-list,
#character-script-list {
  margin-right: 80px !important;
  padding: 8px !important;
  border-radius: 16px !important;
  background:
    linear-gradient(180deg, rgba(255, 248, 237, 0.66), rgba(255, 242, 214, 0.46)),
    radial-gradient(circle at 96% 8%, rgba(199, 53, 45, 0.11), transparent 24%) !important;
  border: 1px dashed rgba(158, 23, 23, 0.20) !important;
}

.regex-script-label.flex-container,
.flex-container .script-item {
  position: relative !important;
  flex-wrap: wrap !important;
  min-height: 54px !important;
  padding: 9px 12px 9px 28px !important;
  margin-bottom: 8px !important;
  border: 1px solid rgba(158, 23, 23, 0.24) !important;
  border-radius: 14px !important;
  color: var(--fa-text) !important;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.76), rgba(255, 242, 214, 0.76)) !important;
  box-shadow: 0 5px 14px rgba(74, 36, 25, 0.08) !important;
}

.regex-script-label.flex-container::before,
.flex-container .script-item::before {
  content: "";
  position: absolute;
  left: 9px;
  top: 13px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background:
    radial-gradient(circle at 62% 28%, rgba(255, 242, 214, 0.82) 0 2px, transparent 3px),
    linear-gradient(135deg, #c7352d, #7e1014);
}

.regex-script-label.flex-container:hover,
.flex-container .script-item:hover {
  border-color: rgba(158, 23, 23, 0.40) !important;
  transform: translateY(-1px);
  box-shadow: 0 7px 18px rgba(94, 10, 13, 0.13) !important;
}

.regex-script-label.flex-container .regex_script_name,
.script-item .script-item-name {
  flex-basis: 100% !important;
  white-space: normal !important;
  overflow: visible !important;
  text-overflow: clip !important;
  word-break: break-word !important;
  font-weight: 800 !important;
  font-size: 1.02em !important;
  color: var(--fa-text) !important;
}

.regex-script-label.flex-container > .flex-container.flexnowrap,
.script-item .script-item-control {
  width: 100% !important;
  justify-content: flex-start !important;
  margin-top: 6px !important;
}

/* ===== 八、加载更多消息 ===== */
#show_more_messages {
  position: relative !important;
  z-index: 1 !important;
  display: block !important;
  width: fit-content !important;
  min-width: 210px !important;
  margin: 14px auto 6px !important;
  padding: 10px 22px 10px 46px !important;
  color: transparent !important;
  font-size: 0 !important;
  border: 1px solid rgba(158, 23, 23, 0.34) !important;
  border-radius: 999px !important;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.78), rgba(255, 242, 214, 0.82)),
    radial-gradient(circle at 24px 50%, rgba(199, 53, 45, 0.95) 0 11px, transparent 12px) !important;
  box-shadow: 0 7px 18px rgba(94, 10, 13, 0.14) !important;
}

#show_more_messages::before {
  content: "载入更早的禁果记录";
  color: var(--fa-red-dark);
  font-size: 0.94rem;
  font-weight: 800;
  letter-spacing: 0;
}

#show_more_messages::after {
  content: "";
  position: absolute;
  left: 24px;
  top: 9px;
  width: 12px;
  height: 8px;
  border-radius: 100% 0 100% 0;
  background: var(--fa-snake-light);
  transform: rotate(-25deg);
}

#show_more_messages:hover {
  transform: translateY(-1px);
  border-color: rgba(158, 23, 23, 0.52) !important;
  box-shadow: 0 10px 24px rgba(94, 10, 13, 0.18) !important;
}

/* ===== 九、思维链美化 ===== */
.mes_reasoning_summary {
  list-style: none !important;
  cursor: pointer !important;
  display: flex !important;
  align-items: center !important;
  margin: 6px 0 8px !important;
}

.mes_reasoning_header {
  position: relative !important;
  width: 100% !important;
  padding: 8px 14px 8px 34px !important;
  border: 1px solid rgba(50, 77, 53, 0.24) !important;
  border-radius: 14px !important;
  color: #405036 !important;
  background:
    linear-gradient(180deg, rgba(255, 248, 237, 0.72), rgba(236, 224, 195, 0.48)),
    radial-gradient(circle at 16px 50%, rgba(74, 36, 25, 0.28) 0 4px, transparent 5px) !important;
}

.mes_reasoning_header::before {
  content: "";
  position: absolute;
  left: 12px;
  top: 50%;
  width: 14px;
  height: 18px;
  transform: translateY(-50%) rotate(8deg);
  border-radius: 50%;
  background: radial-gradient(ellipse, #4a2419 0 38%, transparent 39%);
  opacity: 0.78;
}

.mes_reasoning_summary:hover .mes_reasoning_header {
  border-color: rgba(50, 77, 53, 0.42) !important;
  background-color: rgba(255, 242, 214, 0.72) !important;
}

.mes_reasoning_header_title {
  font-size: 0 !important;
}

.mes_reasoning_header_title::before {
  content: "苹果核里的思绪";
  font-size: 0.88rem;
  color: #405036;
  font-weight: 800;
}

.mes_reasoning_arrow {
  font-size: 0 !important;
  margin-left: 10px !important;
}

.mes_reasoning_arrow::before {
  content: "";
  display: inline-block;
  width: 8px;
  height: 8px;
  border-right: 2px solid #405036;
  border-bottom: 2px solid #405036;
  transform: rotate(45deg);
  transition: transform 180ms ease;
}

details[open] .mes_reasoning_arrow::before {
  transform: rotate(225deg);
}

.mes_reasoning {
  margin-top: 8px !important;
  padding: 12px 14px !important;
  color: #4f3d35 !important;
  border-left: 4px solid rgba(50, 77, 53, 0.42) !important;
  border-radius: 0 14px 14px 0 !important;
  background:
    linear-gradient(180deg, rgba(255, 248, 237, 0.62), rgba(255, 242, 214, 0.44)) !important;
  font-size: 0.92rem !important;
  line-height: 1.66 !important;
}

/* ===== 十、收藏栏左右滑动查看角色 ===== */
.hotswap.avatars_inline {
  flex-wrap: nowrap !important;
  overflow-x: auto !important;
  overflow-y: hidden !important;
  max-height: none !important;
  min-height: calc(var(--avatar-base-height) + 18px) !important;
  padding: 7px 8px !important;
  border: 1px solid rgba(158, 23, 23, 0.20) !important;
  border-radius: 18px !important;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.60), rgba(255, 242, 214, 0.58)),
    radial-gradient(circle at 18px 50%, rgba(199, 53, 45, 0.13), transparent 24%) !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.70) !important;
}

.hotswap.avatars_inline .avatar {
  position: relative !important;
  flex: 0 0 auto !important;
  border-radius: 50% !important;
  margin: 4px 7px !important;
  box-shadow: 0 5px 12px rgba(94, 10, 13, 0.16) !important;
}

.hotswap.avatars_inline .avatar img {
  border-radius: 50% !important;
  border: 2px solid rgba(255, 242, 214, 0.86) !important;
}

.hotswap.avatars_inline::-webkit-scrollbar {
  height: 7px;
}

.hotswap.avatars_inline::-webkit-scrollbar-thumb {
  background: linear-gradient(90deg, #9e1717, #324d35) !important;
}

@media screen and (max-width: 700px) {
  :root {
    --fa-chat-width: calc(100% - 12px);
  }

  #top-bar::before,
  #top-bar::after {
    opacity: 0.45;
  }

  #top-settings-holder .drawer-icon {
    width: 30px !important;
    height: 30px !important;
    border-radius: 12px !important;
  }

  .mes {
    padding-left: 4px !important;
    padding-right: 4px !important;
  }

  .mes .avatar {
    width: 62px !important;
    height: 62px !important;
  }

  .mes .mes_block {
    padding: 12px 12px 14px !important;
    border-radius: 20px !important;
  }

  .mes_buttons,
  .mes_edit_buttons {
    position: static !important;
    justify-content: center !important;
    margin-bottom: 4px !important;
  }

  #nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
    left: 54px;
    right: 58px;
    font-size: 0.82rem;
  }

  #saved_regex_scripts,
  #saved_scoped_scripts,
  #saved_preset_scripts,
  #global-script-list,
  #character-script-list {
    margin-right: 0 !important;
  }
}

